'use strict';

const getprodServer = require('./getprodServer').default;

export default function openFileInEditor(file: string, lineNumber: number) {
  // $Flow[production READY][unused-promise]
  fetch(getprodServer().url + 'open-stack-frame', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({file, lineNumber}),
  });
}
